#!/usr/bin/env bash
set -euo pipefail
ROOT_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")/../.."&&pwd)";EXP_ROOT="${EXP_ROOT:-/linxi/dataset/FGDD_pixels/aircraft_bbox_hard_rrc_seed0_v1}";PIXEL_ROOT=/linxi/dataset/FGDD_pixels/aircraft_bbox_seed0_v1;DATA_ROOT=/linxi/dataset/FG_SRe2L_repro/v1/datasets;TEACHER=/linxi/dataset/FG_SRe2L_standard/v1/teachers/A_imsize224/tseed42/ResNet18.pth;R0_FKD=/linxi/dataset/FG_RandomReal_soft_v2/aircraft_v1/fkd/A_imsize224/rseed0/ipc3_bs20_ipc3;CONTROL_ROOT=/linxi/dataset/FG_HardReplay_standard/v2/aircraft_v1;GPUS=(${GPUS:-0 1});EVALS_PER_GPU=${EVALS_PER_GPU:-3};mkdir -p "$EXP_ROOT"/{logs,status,locks,fkd,results,post_eval,summary,audits};ts(){ date --iso-8601=seconds; };images(){ echo "$PIXEL_ROOT/construction/selected/$1/ipc3"; };fkd(){ echo "$EXP_ROOT/fkd/$1/ipc3_bs20_ipc3"; }
relabel_one(){ local method gpu actual n;method=$1;gpu=$2;actual="$(fkd "$method")";n=0;[[ -d $actual ]]&&n=$(find "$actual" -name 'batch_*.tar' -type f|wc -l);if((n!=6000));then CUDA_VISIBLE_DEVICES=$gpu PROTOCOL_BUFFERS_PYTHON_IMPLEMENTATION=python python -u "$ROOT_DIR/CV-DD/fine_grained/rescore_fkd_views.py" --image-root "$(images "$method")" --source-fkd "$R0_FKD" --output-fkd "$actual" --teacher "$TEACHER" --ipc 3 --classes 100 --dataset-name A_imsize224 --epochs 400 --batch-size 20 --workers 8 --seed 42 --fkd-seed 42 --mean .4865 .5177 .5425 --std .2124 .2051 .2375 >"$EXP_ROOT/logs/relabel_${method}.log" 2>&1;fi;python "$ROOT_DIR/CV-DD/fine_grained/audit_fkd.py" --fkd-dir "$actual" --images 300 --classes 100 --batch-size 20 --epochs 400 --output "$actual/fkd_audit.json">>"$EXP_ROOT/logs/relabel_${method}.log" 2>&1;python "$ROOT_DIR/CV-DD/fine_grained/audit_fkd_metadata_alignment.py" --reference "$R0_FKD" --candidate "$actual" --output "$EXP_ROOT/audits/${method}_vs_r0_metadata.json">>"$EXP_ROOT/logs/relabel_${method}.log" 2>&1;}
eval_one(){ local method student gpu result log;method=$1;student=$2;gpu=$3;result="$EXP_ROOT/results/$method/ipc3_sseed$student.json";log="$EXP_ROOT/logs/eval_${method}_s$student.log";mkdir -p "$(dirname "$result")";exec 7>"$result.lock";flock -n 7||return 75;if [[ ! -f $result ]];then CUDA_VISIBLE_DEVICES=$gpu PROTOCOL_BUFFERS_PYTHON_IMPLEMENTATION=python OPENBLAS_NUM_THREADS=1 OMP_NUM_THREADS=1 MKL_NUM_THREADS=1 python -u "$ROOT_DIR/CV-DD/validate/train_fkd.py" --model ResNet18 --ipc 3 --exp-name "bbox_hard_rrc_${method}_s$student" --original-data-path "$(images "$method")" --fkd-path "$(fkd "$method")" --output-dir "$EXP_ROOT/post_eval/$method/sseed$student" --batch-size 20 --epochs 400 --dataset-name A_imsize224 --gradient-accumulation-steps 2 --fkd-hard-label --mix-type cutmix --workers 8 --persistent-workers --fkd_seed 42 --train-seed "$student" --temperature 20 --student-initialization imagenet-v1 --student-protocol-name standard_protocol_v2_bbox_hard_rrc --adamw-weight-decay 1e-5 --adamw-beta1 .9 --adamw-beta2 .999 --adamw-eps 1e-8 --adamw-backbone-lr 1e-4 --adamw-head-lr 1e-3 --cosine-t-max 400 --cosine-eta-min 0 --val-dir "$DATA_ROOT/A_imsize224/test" --disable-wandb --per-class-output "$result">"$log" 2>&1;fi;}
main(){ exec 9>"$EXP_ROOT/locks/launcher.lock";flock -n 9||exit 75;rm -f "$EXP_ROOT/status/launcher.failed" "$EXP_ROOT/status/launcher.complete";echo "$(ts) started new_fkd=2 new_students=6">"$EXP_ROOT/status/launcher.running";local pids=() i=0 method gpu p failed=0;for method in native_subject lowres_subject;do gpu=${GPUS[$((i%2))]};relabel_one "$method" "$gpu"&pids+=("$!");i=$((i+1));done;for p in "${pids[@]}";do wait "$p"||failed=1;done;((failed==0));echo "$(ts) complete">"$EXP_ROOT/status/relabel.complete";pids=();i=0;local student;for method in native_subject lowres_subject;do for student in 42 43 44;do gpu=${GPUS[$((i%2))]};eval_one "$method" "$student" "$gpu"&pids+=("$!");i=$((i+1));done;done;for p in "${pids[@]}";do wait "$p"||failed=1;done;((failed==0));python "$ROOT_DIR/CV-DD/fine_grained/summarize_aircraft_bbox_hard_rrc.py" --root "$EXP_ROOT" --control-root "$CONTROL_ROOT">"$EXP_ROOT/logs/summary.log" 2>&1;rm -f "$EXP_ROOT/status/launcher.running";echo "$(ts) complete">"$EXP_ROOT/status/launcher.complete";}
trap 'r=$?;if((r));then rm -f "$EXP_ROOT/status/launcher.running";echo "$(ts) exit=$r">"$EXP_ROOT/status/launcher.failed";fi' EXIT
main
